#include <stack>
#include <cassert>
#include <iostream>

int main() {
    std::stack<int> values;
    values.push(2);
    values.push(7);
    assert(values.top() == 7);

    std::stack<int> copy;
    copy = values;
    assert(copy == values);
    values.pop();
    assert(values.top() == 2);
    std::cout << "Checks passed\n";
}
